diff --git a/src/test/java/com/example/service/UserServiceTest.java b/src/test/java/com/example/service/UserServiceTest.java
--- a/src/test/java/com/example/service/UserServiceTest.java
+++ b/src/test/java/com/example/service/UserServiceTest.java
@@ -0,0 +1,42 @@
+package com.example.service;
+
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.api.extension.ExtendWith;
+import org.mockito.InjectMocks;
+import org.mockito.Mock;
+import org.mockito.junit.jupiter.MockitoExtension;
+
+import java.util.Optional;
+
+import static org.assertj.core.api.Assertions.*;
+import static org.mockito.Mockito.*;
+
+@ExtendWith(MockitoExtension.class)
+class UserServiceTest {
+
+    @Mock UserRepository userRepository;
+    @InjectMocks UserService userService;
+
+    @Test
+    void getUserById_returnsUser_whenFound() {
+        var user = new User(1L, "alice@example.com", "Alice");
+        when(userRepository.findById(1L)).thenReturn(Optional.of(user));
+        var result = userService.getUserById(1L);
+        assertThat(result.getEmail()).isEqualTo("alice@example.com");
+    }
+
+    @Test
+    void getUserById_throwsNotFoundException_whenMissing() {
+        when(userRepository.findById(99L)).thenReturn(Optional.empty());
+        assertThatThrownBy(() -> userService.getUserById(99L))
+            .isInstanceOf(UserNotFoundException.class);
+    }
+}

